CREATE OR REPLACE FUNCTION public.accept_friend_request(request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  sender_id UUID;
  receiver_id UUID;
BEGIN
  -- Get the request details
  SELECT fr.sender_id, fr.receiver_id 
  INTO sender_id, receiver_id
  FROM public.friend_requests fr 
  WHERE fr.id = request_id AND fr.receiver_id = auth.uid() AND fr.status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Friend request not found or not authorized';
  END IF;

  -- Update the request status
  UPDATE public.friend_requests 
  SET status = 'accepted', updated_at = now()
  WHERE id = request_id;

  -- Create friendship (ensure consistent ordering)
  IF sender_id < receiver_id THEN
    INSERT INTO public.friends (user1_id, user2_id) VALUES (sender_id, receiver_id);
  ELSE
    INSERT INTO public.friends (user1_id, user2_id) VALUES (receiver_id, sender_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_ai_quota(p_endpoint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user UUID := auth.uid();
  v_plan TEXT;
  v_now TIMESTAMPTZ := now();
  r RECORD;
  v_count INTEGER;
  v_start TIMESTAMPTZ;
  v_remaining INTEGER := NULL;
  v_resets TIMESTAMPTZ := NULL;
  v_any BOOLEAN := false;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'plan', 'free', 'pro_only', false, 'remaining', 0, 'resets_at', NULL);
  END IF;
  v_plan := public.effective_plan();

  DELETE FROM public.ai_usage
   WHERE user_id = v_user AND endpoint = p_endpoint AND window_start < v_now - INTERVAL '35 days';

  FOR r IN SELECT window_kind, max_count FROM public.plan_limits WHERE plan = v_plan AND endpoint = p_endpoint LOOP
    v_any := true;
    v_start := public.ai_window_start(r.window_kind, v_now);
    SELECT request_count INTO v_count FROM public.ai_usage
     WHERE user_id = v_user AND endpoint = p_endpoint AND window_kind = r.window_kind AND window_start = v_start;
    v_count := COALESCE(v_count, 0);
    IF v_count >= r.max_count THEN
      RETURN jsonb_build_object(
        'allowed', false, 'plan', v_plan, 'pro_only', r.max_count = 0,
        'remaining', 0, 'resets_at', public.ai_window_end(r.window_kind, v_start));
    END IF;
    IF v_remaining IS NULL OR (r.max_count - v_count - 1) < v_remaining THEN
      v_remaining := r.max_count - v_count - 1;
      v_resets := public.ai_window_end(r.window_kind, v_start);
    END IF;
  END LOOP;

  IF v_any THEN
    FOR r IN SELECT window_kind FROM public.plan_limits WHERE plan = v_plan AND endpoint = p_endpoint LOOP
      v_start := public.ai_window_start(r.window_kind, v_now);
      INSERT INTO public.ai_usage AS u (user_id, endpoint, window_kind, window_start, request_count)
      VALUES (v_user, p_endpoint, r.window_kind, v_start, 1)
      ON CONFLICT (user_id, endpoint, window_kind, window_start)
      DO UPDATE SET request_count = u.request_count + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('allowed', true, 'plan', v_plan, 'pro_only', false, 'remaining', v_remaining, 'resets_at', v_resets);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_dm_room(other_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  current_user_id uuid;
  existing_room_id uuid;
  new_room_id uuid;
  user1_id uuid;
  user2_id uuid;
BEGIN
  -- Get current user ID
  current_user_id := auth.uid();

  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;

  IF current_user_id = other_user_id THEN
    RAISE EXCEPTION 'Cannot create DM with yourself';
  END IF;

  -- Ensure consistent ordering (smaller UUID first)
  IF current_user_id < other_user_id THEN
    user1_id := current_user_id;
    user2_id := other_user_id;
  ELSE
    user1_id := other_user_id;
    user2_id := current_user_id;
  END IF;

  -- Check if a DM room already exists between these two users
  SELECT cr.id INTO existing_room_id
  FROM public.chat_rooms cr
  WHERE cr.is_group = false
    AND EXISTS (
      SELECT 1 FROM public.chat_room_participants crp1
      WHERE crp1.room_id = cr.id AND crp1.user_id = user1_id
    )
    AND EXISTS (
      SELECT 1 FROM public.chat_room_participants crp2
      WHERE crp2.room_id = cr.id AND crp2.user_id = user2_id
    )
    AND (
      SELECT COUNT(*) FROM public.chat_room_participants crp3
      WHERE crp3.room_id = cr.id
    ) = 2; -- Ensure it's only a 2-person chat

  -- If room exists, return it
  IF existing_room_id IS NOT NULL THEN
    RETURN existing_room_id;
  END IF;

  -- Create new DM room
  INSERT INTO public.chat_rooms (is_group, name)
  VALUES (false, NULL)
  RETURNING id INTO new_room_id;

  -- Add both participants to the room
  INSERT INTO public.chat_room_participants (room_id, user_id)
  VALUES 
    (new_room_id, user1_id),
    (new_room_id, user2_id);

  RETURN new_room_id;
END;
$function$
